using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running this app.");

const string modelId = "gpt-4o-mini-2024-07-18";

IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

var notepad = new ResearchNotepad();

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research assistant. When given a topic you:
        1. Search the web for relevant information (perform 2-3 searches with varied queries).
        2. Save the most important findings as notes.
        3. After gathering enough information, produce a concise summary of your findings.

        Always search before summarizing. Include key facts, dates, and sources in your notes.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and taking notes.",
    tools: [
        AIFunctionFactory.Create(SearchWeb),
        AIFunctionFactory.Create(notepad.SaveNote),
        AIFunctionFactory.Create(notepad.GetNotes),
    ]);

Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       AI Research Agent               ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

string topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

Console.WriteLine($"\nResearching: {topic}\n");
Console.WriteLine(new string('─', 50));

var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
});

var response = await agent.RunAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    session: null,
    options: runOptions);

Console.WriteLine();
Console.WriteLine(new string('═', 50));
Console.WriteLine("RESEARCH SUMMARY");
Console.WriteLine(new string('═', 50));

foreach (var message in response.Messages)
{
    if (message.Role == ChatRole.Assistant && message.Text is { Length: > 0 } text)
    {
        Console.WriteLine(text);
    }
}

Console.WriteLine();
Console.WriteLine(new string('─', 50));
Console.WriteLine($"Notes collected: {notepad.Count}");
foreach (var note in notepad.AllNotes)
{
    Console.WriteLine($"  • {note}");
}

// --- Tool definitions ---

[Description("Search the web for information on a given query. Returns a list of search result snippets.")]
static IReadOnlyList<string> SearchWeb(
    [Description("The search query to look up on the web.")] string query)
{
    Console.WriteLine($"  🔍 Searching: \"{query}\"");

    // Simulated search results keyed on common research terms.
    // In production, replace with a real search API (e.g., Bing Search).
    var results = new List<string>();
    var lowerQuery = query.ToLowerInvariant();

    if (lowerQuery.Contains("quantum computing"))
    {
        results.AddRange([
            "Quantum computing uses qubits that can exist in superposition, enabling parallel computation. IBM unveiled a 1,121-qubit Condor processor in Dec 2023. (Source: IBM Research)",
            "Google's Willow chip (2024) demonstrated quantum error correction below threshold for the first time, a key milestone toward fault-tolerant quantum computers. (Source: Google AI Blog)",
            "Applications include cryptography, drug discovery, optimization, and materials science. Estimated $450B market by 2040. (Source: McKinsey Report 2024)",
        ]);
    }
    else if (lowerQuery.Contains("artificial intelligence") || lowerQuery.Contains(" ai ") || lowerQuery.StartsWith("ai "))
    {
        results.AddRange([
            "Generative AI market projected to reach $1.3 trillion by 2032, growing at 42% CAGR. (Source: Bloomberg Intelligence)",
            "Major 2024 milestones: GPT-4o multimodal model, Claude 3, Gemini 1.5 with 1M-token context. (Source: TechCrunch)",
            "AI regulation advancing globally: EU AI Act entered force Aug 2024; US executive order on AI safety. (Source: Reuters)",
        ]);
    }
    else if (lowerQuery.Contains("climate") || lowerQuery.Contains("renewable"))
    {
        results.AddRange([
            "Global renewable energy capacity grew by 50% in 2023, led by solar PV. China accounted for nearly 60% of new additions. (Source: IEA)",
            "2023 was the hottest year on record at 1.48°C above pre-industrial levels. (Source: Copernicus Climate Change Service)",
            "Battery storage deployments tripled in 2023, with costs falling 14% year-over-year. (Source: BloombergNEF)",
        ]);
    }
    else if (lowerQuery.Contains("space") || lowerQuery.Contains("mars") || lowerQuery.Contains("nasa"))
    {
        results.AddRange([
            "NASA's Artemis II mission planned for 2025 will send astronauts around the Moon for the first time since Apollo. (Source: NASA)",
            "SpaceX Starship completed its first successful orbital test flight in 2024. (Source: SpaceX Updates)",
            "James Webb Space Telescope discovered the earliest known galaxies, forming just 300 million years after the Big Bang. (Source: Nature Astronomy)",
        ]);
    }
    else
    {
        results.AddRange([
            $"Search result 1 for '{query}': Recent developments indicate significant progress in this area with multiple research institutions publishing findings in 2024.",
            $"Search result 2 for '{query}': Industry analysts project continued growth and investment, with global spending expected to increase 25% annually.",
            $"Search result 3 for '{query}': Key challenges remain around scalability, cost reduction, and regulatory frameworks according to recent policy papers.",
        ]);
    }

    return results;
}

static string PromptForTopic()
{
    Console.Write("Enter a research topic: ");
    var topic = Console.ReadLine()?.Trim();
    return string.IsNullOrEmpty(topic) ? "quantum computing" : topic;
}

// --- Note-taking tool ---

sealed class ResearchNotepad
{
    private readonly List<string> _notes = [];

    public int Count => _notes.Count;
    public IReadOnlyList<string> AllNotes => _notes;

    [Description("Save a research note capturing an important finding.")]
    public string SaveNote(
        [Description("The note text to save.")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📝 Note saved ({_notes.Count} total)");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all saved research notes.")]
    public IReadOnlyList<string> GetNotes()
    {
        Console.WriteLine($"  📋 Retrieving {_notes.Count} note(s)");
        return _notes;
    }
}

